use aeterna_v1::education::{AnswerMode,Fact,School,TeachingExample,ground};
use aeterna_v1::construction::vm::{Expr,Library,Op,Value,Error};
use aeterna_v1::construction::induction::{infer,Example,InductionConfig};
use aeterna_v1::scientific_runtime::ScientificRuntime;
use aeterna_v1::construction::Config;
use aeterna_v1::construction::autonomy::AutonomyPolicy;
fn runtime()->ScientificRuntime{ScientificRuntime::new_constructing(Config{width:32,actions:4,..Default::default()},AutonomyPolicy::default(),vec![0;32],"school-test").unwrap()}
fn lesson(prefix:&str,f:fn(i64,i64)->i64)->Vec<TeachingExample>{
    (0..32).map(|i|{let a=3+i;let b=2+(i*7)%29;TeachingExample{question:format!("{prefix} {a} и {b}?"),answer:f(a,b),source:format!("authored-teacher:{i}")}}).collect()
}
#[test]fn acquired_rule_solves_unseen_numbers(){let mut r=runtime();let l=r.teach_school(lesson("Найди сумму",|a,b|a+b)).unwrap();assert!(l.accepted);let a=r.answer_school("Найди сумму 137 и 58?",AnswerMode::All).unwrap();assert_eq!(a.answer.as_deref(),Some("195"));assert_eq!(a.method,"induced_vm");}
#[test]fn arbitrary_unknown_vocabulary_is_learned_not_a_subject_dispatch(){let mut r=runtime();assert!(r.answer_school("zqv 107 и 21?",AnswerMode::All).unwrap().answer.is_none());assert!(r.teach_school(lesson("zqv",|a,b|a*b)).unwrap().accepted);assert_eq!(r.answer_school("zqv 107 и 21?",AnswerMode::All).unwrap().answer.as_deref(),Some("2247"));}
#[test]fn same_numbers_do_not_solve_an_unlearned_instruction(){let mut r=runtime();r.teach_school(lesson("Сложи",|a,b|a+b)).unwrap();assert!(r.answer_school("Вычти 137 и 58?",AnswerMode::All).unwrap().answer.is_none());}
#[test]fn repeated_inputs_cannot_be_passed_off_as_evidence(){let mut r=runtime();let e=lesson("sum",|a,b|a+b)[0].clone();assert!(r.teach_school(vec![e;32]).is_err());}
#[test]fn prospective_validation_cannot_train_the_candidate(){let mut r=runtime();let mut data=lesson("sum",|a,b|a+b);for e in &mut data[24..]{e.answer+=1;}let report=r.teach_school(data.clone()).unwrap();assert!(!report.accepted);assert_eq!(report.validation_correct,0);assert!(r.answer_school("sum 137 и 58?",AnswerMode::All).unwrap().answer.is_none());assert_eq!(r.teach_school(data).unwrap_err(),Error::Stale);}
#[test]fn freeze_prevents_all_teacher_updates(){let mut r=runtime();r.teach_school(lesson("sum",|a,b|a+b)).unwrap();r.freeze_constructing().unwrap();let before=r.checkpoint_constructing().unwrap();assert!(r.teach_school(lesson("product",|a,b|a*b)).is_err());assert!(r.teach_school_facts(vec![]).is_err());assert_eq!(before,r.checkpoint_constructing().unwrap());}
#[test]fn questions_are_read_only_including_failed_ones(){let mut r=runtime();r.teach_school(lesson("sum",|a,b|a+b)).unwrap();r.freeze_constructing().unwrap();let before=r.checkpoint_constructing().unwrap();for q in ["sum 100 и 45?","Who are you?","sum 1.2 и 3?",""]{let _=r.answer_school(q,AnswerMode::All);}assert_eq!(before,r.checkpoint_constructing().unwrap());}
#[test]fn checkpoint_reproduces_learned_answers_and_native_weights(){let mut r=runtime();r.teach_school(lesson("sum",|a,b|a+b)).unwrap();r.freeze_constructing().unwrap();let bytes=r.checkpoint_constructing().unwrap();let other=ScientificRuntime::from_constructing_checkpoint(&bytes).unwrap();assert_eq!(bytes,other.checkpoint_constructing().unwrap());assert_eq!(other.answer_school("sum 37 и 29?",AnswerMode::All).unwrap().answer.as_deref(),Some("66"));assert_eq!(r.unified_report().unwrap().native_weights,other.unified_report().unwrap().native_weights);}
#[test]fn science_facts_are_marked_as_recall_not_as_invention(){let mut r=runtime();r.teach_school_facts(vec![Fact{question:"Test question?".into(),answer:"Teacher statement".into(),source:"fixture".into()}]).unwrap();let a=r.answer_school("TEST QUESTION?",AnswerMode::All).unwrap();assert_eq!(a.answer.as_deref(),Some("Teacher statement"));assert_eq!(a.method,"teacher_recall");}
#[test]fn conflicting_sources_cause_abstention(){let mut r=runtime();r.teach_school_facts(["yes","no"].iter().map(|s|Fact{question:"A fact?".into(),answer:s.to_string(),source:s.to_string()}).collect()).unwrap();let a=r.answer_school("A fact?",AnswerMode::All).unwrap();assert!(a.answer.is_none());assert_eq!(a.reason,"contradictory_teacher_sources");}
#[test]fn arithmetic_ablation_keeps_examples_but_removes_generalization(){let mut r=runtime();r.teach_school(lesson("sum",|a,b|a+b)).unwrap();assert_eq!(r.answer_school("sum 137 и 58?",AnswerMode::All).unwrap().answer.as_deref(),Some("195"));assert!(r.answer_school("sum 137 и 58?",AnswerMode::RecallOnly).unwrap().answer.is_none());}
#[test]fn multiple_lexical_bindings_reuse_one_acquired_function(){let mut r=runtime();r.teach_school(lesson("sum",|a,b|a+b)).unwrap();r.teach_school(lesson("alt-sum",|a,b|a+b)).unwrap();assert_eq!(r.school_report().unwrap().acquired_skills,2);assert_eq!(r.school_report().unwrap().library_functions,1);}
#[test]fn domain_change_preserves_school_knowledge(){let mut r=runtime();r.teach_school(lesson("sum",|a,b|a+b)).unwrap();r.enter_constructing_domain("another",Config{width:32,actions:4,..Default::default()},AutonomyPolicy::default(),vec![7;32]).unwrap();assert_eq!(r.answer_school("sum 137 и 58?",AnswerMode::All).unwrap().answer.as_deref(),Some("195"));}
#[test]fn prior_snapshot_cannot_rewind_school_without_rewinding_external_actions(){let mut r=runtime();let old=r.checkpoint_constructing().unwrap();r.teach_school(lesson("sum",|a,b|a+b)).unwrap();assert_eq!(r.restore_constructing(&old),Err(Error::Stale));}
#[test]fn exact_integer_division_never_silently_truncates(){assert_eq!(Op::DivExact.apply(Value::Int(12),Value::Int(3)),Ok(Value::Int(4)));assert!(Op::DivExact.apply(Value::Int(7),Value::Int(2)).is_err());assert!(Op::DivExact.apply(Value::Int(1),Value::Int(0)).is_err());assert!(Op::DivExact.apply(Value::Int(i64::MIN),Value::Int(-1)).is_err());}
#[test]fn decimal_and_fraction_syntax_not_misrepresented_as_integer_answer(){assert!(ground("x 12.5 и 3").is_err());assert!(ground("x 12,5 и 3").is_err());assert_eq!(ground("x -12 и 3").unwrap().1,[-12,3]);}
#[test]fn opaque_subject_id_and_solution_program_are_not_accepted(){let data=serde_json::json!({"question":"sum 3 и 4?","answer":7,"source":"teacher","program":"Add"});assert!(serde_json::from_value::<TeachingExample>(data).is_err());}
#[test]fn semantic_replay_rejects_a_tampered_acquired_program(){let mut school=School::default();school.teach(lesson("sum",|a,b|a+b)).unwrap();let mut v=serde_json::to_value(school).unwrap();v["library"]["functions"][0]["body"]=serde_json::to_value(Expr::integer(0)).unwrap();let forged:School=serde_json::from_value(v).unwrap();assert!(forged.validate().is_err());}
#[test]fn induction_budget_is_bounded_even_when_no_program_fits(){let data:Vec<_>=(1..25).map(|i|Example{input:vec![i],output:(i*i*i*i+7*i)%131}).collect();let r=infer(&data,&Library::default(),&InductionConfig{work:1000,..Default::default()}).unwrap();assert!(r.work<=1000);assert!(r.expression.is_none());assert!(r.truncated);}
#[test]fn untrained_cold_state_has_no_school_answers(){let r=runtime();assert!(r.answer_school("Найди площадь 8 и 9",AnswerMode::All).unwrap().answer.is_none());assert!(r.school_report().is_none());}
#[test]fn reordered_known_words_use_a_marked_lexical_hypothesis(){let mut r=runtime();r.teach_school(lesson("Найди сумму",|a,b|a+b)).unwrap();r.freeze_constructing().unwrap();let before=r.checkpoint_constructing().unwrap();let answer=r.answer_school("Сумму найди 137 и 58?",AnswerMode::All).unwrap();assert_eq!(answer.answer.as_deref(),Some("195"));assert_eq!(answer.method,"induced_vm_lexical");assert_eq!(before,r.checkpoint_constructing().unwrap());}
#[test]fn a_similar_question_with_other_numbers_cannot_recall_an_old_numeric_answer(){let mut r=runtime();r.teach_school_facts(vec![Fact{question:"A long descriptive question about a payment of 15 and a payment of 17 in a carefully specified situation".into(),answer:"32".into(),source:"fixture".into()}]).unwrap();assert!(r.answer_school("A long descriptive question about a payment of 19 and a payment of 21 in a carefully specified situation",AnswerMode::All).unwrap().answer.is_none());}
